function toRad(deg){ return deg*Math.PI/180; }
function bounds(w, h, deg){ var r=toRad(deg); return { w: Math.abs(w*Math.cos(r)) + Math.abs(h*Math.sin(r)),
                                                       h: Math.abs(w*Math.sin(r)) + Math.abs(h*Math.cos(r)) }; }
function canvasSize(w, h, deg){ var b=bounds(w,h,deg); return { w: Math.ceil(b.w), h: Math.ceil(b.h) }; }
var EXPORTS={ toRad:toRad, bounds:bounds, canvasSize:canvasSize };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RotateForgePure = EXPORTS; }
